B.cho={"*\u0645\u0644\u062e\u0635 \u0623\u0633\u0628\u0648\u0639\u064a - {p}*\n{a} \u0625\u0644\u0649 {b}\n\n{s}":0,[u.u]:1,[u.mK]:2,"\u0623\u0636\u0641":3,"\u0623\u0636\u0641 \u0627\u0644\u0628\u0627\u0642\u064a \u0643\u0644\u0647\u0627":4,"\u0627\u062a\u062d\u0641\u0638\u062a \u0641\u064a \u064a\u0648\u0645\u064a\u0629 {d}":5,"\u0627\u062a\u0636\u0627\u0641\u062a {n} \u0645\u0644\u0627\u062d\u0638\u0629":6,"\u0627\u062a\u0642\u0631\u0627 {n} \u0645\u0644\u0641 PDF.":7,"\u0627\u062d\u0641\u0638 \u0641\u064a \u0627\u0644\u064a\u0648\u0645\u064a\u0629":8,"\u0627\u062d\u0643\u064a \u0639\u0646 \u0634\u063a\u0644 \u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)":9,"\u0627\u062e\u062a\u0627\u0631":10,"\u0627\u0633\u0623\u0644":11,"\u0627\u0633\u0623\u0644 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a":12,[u.nh]:13,"\u0627\u0642\u062a\u0631\u0627\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a":14,"\u0627\u0642\u062a\u0631\u0627\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a (RFI)":15,"\u0627\u0642\u062a\u0631\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a":16,"\u0627\u0642\u0631\u0623 \u0645\u0644\u0641\u0627\u062a PDF \u0627\u0644\u0645\u0637\u0627\u0628\u0642\u0629 (\u0644\u062d\u062f 3)":17,"\u0627\u0643\u062a\u0628 \u0633\u0624\u0627\u0644\u0643 \u0627\u0644\u0623\u0648\u0644.":18,"\u0627\u0643\u062a\u0628 \u0645\u0644\u062e\u0635 \u0622\u062e\u0631 7 \u0623\u064a\u0627\u0645":19,"\u0627\u0643\u062a\u0628\u0647 \u062a\u0627\u0646\u064a":20,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629":21,"\u0627\u0644\u062e\u062f\u0645\u0629 \u0645\u0634\u063a\u0648\u0644\u0629 \u062f\u0644\u0648\u0642\u062a\u064a. \u062c\u0631\u0651\u0628 \u0628\u0639\u062f \u0634\u0648\u064a\u0629.":22,"\u0627\u0644\u0645\u0631\u0627\u062c\u0639":23,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0627\u0644\u0630\u0643\u064a \u0645\u062d\u062a\u0627\u062c \u0646\u062a \u0648\u0633\u064a\u0631\u0641\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639. \u0627\u0644\u0646\u0633\u062e\u0629 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\u0629 \u0623\u0648 \u0645\u0646 \u063a\u064a\u0631 \u0627\u062a\u0635\u0627\u0644 \u0645\u0634 \u0628\u062a\u062f\u0639\u0645\u0647\u060c \u0648\u0628\u0627\u0642\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0634\u063a\u0627\u0644 \u0639\u0627\u062f\u064a.":24,[u.mf]:25,[u.bp]:26,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0631\u0641\u0636 \u0627\u0644\u0637\u0644\u0628 \u062f\u0647.":27,[u.kC]:28,[u.jP]:29,[u.jp]:30,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0645\u0627\u0643\u062a\u0628\u0634 \u0645\u0644\u062e\u0635. \u062c\u0631\u0651\u0628 \u062a\u0627\u0646\u064a.":31,"\u0627\u0644\u0645\u0644\u062e\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a":32,"\u062a\u0636\u064a\u0641 {n} \u0645\u0644\u0627\u062d\u0638\u0629 \u0644\u0644\u0645\u0634\u0631\u0648\u0639\u061f":33,"\u062c\u0647\u0651\u0632 \u0627\u0644\u0645\u0633\u0648\u062f\u0629":34,"\u062c\u0647\u0651\u0632 \u0645\u0633\u0648\u062f\u0629 \u062a\u0627\u0646\u064a\u0629":35,"\u062d\u0635\u0644\u062a \u0645\u0634\u0643\u0644\u0629 \u063a\u064a\u0631 \u0645\u062a\u0648\u0642\u0639\u0629: {e}":36,"\u062d\u0635\u0644\u062a \u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0639\u062f{c}. \u062c\u0631\u0651\u0628 \u062a\u0627\u0646\u064a.":37,[u.nY]:38,"\u062f\u0627\u0644\u0629 \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0644\u0633\u0647 \u0645\u0634 \u0645\u062a\u0631\u0643\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u0631\u0641\u0631.":39,"\u0631\u0627\u062c\u0639 \u0648\u0623\u0636\u0641":40,"\u0631\u0627\u062c\u0639 \u0648\u0639\u062f\u0651\u0644 \u0642\u0628\u0644 \u0627\u0644\u062d\u0641\u0638":41,"\u0631\u062f \u063a\u064a\u0631 \u0645\u062a\u0648\u0642\u0639 \u0645\u0646 \u0627\u0644\u0633\u064a\u0631\u0641\u0631.":42,"\u0633\u0624\u0627\u0644\u0643":43,"\u0635\u0648\u0651\u0631":44,[u.p0]:45,[u.mo]:46,"\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647: {u} \u0645\u0646 {l}":47,[u.ek]:48,"\u0644\u0627\u0632\u0645 \u062a\u0633\u062c\u0644 \u062f\u062e\u0648\u0644\u0643 \u0627\u0644\u0623\u0648\u0644.":49,[u.fn]:50,[u.oR]:51,"\u0645\u0633\u0648\u062f\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629":52,"\u0645\u0634 \u0645\u0633\u0645\u0648\u062d\u0644\u0643 \u062a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0641\u064a \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u062f\u0647.":53,"\u0645\u0634 \u0645\u0633\u0645\u0648\u062d\u0644\u0643 \u062a\u0639\u062f\u0651\u0644 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u062f\u064a.":54,"\u0645\u0634\u0627\u0631\u0643\u0629 (\u0648\u0627\u062a\u0633\u0627\u0628)":55,[u.k_]:56,"\u0645\u0641\u064a\u0634 \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a \u0645\u0642\u062a\u0631\u062d\u0629 \u0627\u0644\u0645\u0631\u0629 \u062f\u064a.":57,[u.ik]:58,"\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0642\u062a\u0631\u062d\u0629 ({n})":59,"\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0646 \u0641\u064a\u062f\u064a\u0648":60,[u.ed]:61,[u.h6]:62}
B.bZI=s(["*Weekly summary - {p}*\n{a} to {b}\n\n{s}","*R\xe9sum\xe9 hebdomadaire - {p}*\n{a} au {b}\n\n{s}"],t.s)
B.buY=s(["Last 7 days: progress, issues, delays and cost, ready for WhatsApp","7 derniers jours : avancement, probl\xe8mes, retards et co\xfbts, pr\xeat pour WhatsApp"],t.s)
B.bUM=s(["Slower and a bit costlier; works on documents uploaded to the server","Plus lent et un peu plus co\xfbteux ; travaille sur les documents envoy\xe9s au serveur"],t.s)
B.bXc=s(["Add all the rest","Ajouter tout le reste"],t.s)
B.c0s=s(["Saved to the daily log of {d}","Enregistr\xe9 dans le journal du {d}"],t.s)
B.bS8=s(["{n} observation(s) added","{n} observation(s) ajout\xe9e(s)"],t.s)
